BLI_st.name='BLI'; 
BLI_st.lat=38.9761;
BLI_st.lon=-120.103;
BLI_st.alt=2130;
%%
BLI_rd=read_betsy('bliss_head',BLI_st.name);
%%
datevec(BLI_rd.Time(1)) %[output:9c4ee211]
datevec(BLI_rd.Time(end)) %[output:8aea1497]
prctile(BLI_rd.U_S,[5, 50, 95]) %[output:6dd43187]
plotFigControl(BLI_rd,BLI_st.name); %[output:4ee9fbd0] %[output:20cc2468] %[output:73fe9575] %[output:4c7ca66a] %[output:9050a970] %[output:665afeb5] %[output:260e1467] %[output:5e34cffd] %[output:76332b90]
% 1 size cut,
% sc: ok, clear seasonal cycle, max in summer, some negatives
%[text] lambdaSC=\[450;550;700\]\*ones(1,4); lambdaAE3=\[467;530;660\]\*ones(1,4); lambdaAE7=\[370 470 520 590 660 880 950\]; BLI\_cal=compute\_exp\_SSA(BLI\_rd,lambdaSC, lambdaAE3); plotFigControl\_cal(BLI\_cal, BLI\_st.name);
%%
%Questions:
%problems:
% station parameters: no question!
%%
BLI_tr=BLI_rd;
BLI_tr.y=year(BLI_tr.Time);
%eneleve une valeur de 2019
BLI_tr=BLI_tr(1:end-1,:);
% begin at the beginning of a year: 1997
%end year: 2006
P=timerange('1997-01-01','2006-01-01');
BLI_tr=BLI_tr(P,:);

%see outliers
names=fieldnames(BLI_tr);
c= startsWith(names,["T1";"T0";"T_";"P_";"P1_";"P0_"]) | endsWith(names,'T');
N=names(c);
for i=1:length(N)
    BLI_tr.(N{i})=[];
end

